oice['currency']) ?></strong></p><p>Genel toplam <strong><?= number_format((float)$invoice['grand_total'],2,',','.') ?> <?= kd_e($invoice['currency']) ?></strong></p><p>Ödenen <strong><?= number_format($paid,2,',','.') ?> <?= kd_e($invoice['currency']) ?></strong></p><p>Kalan <strong><?= number_format($remaining,2,',','.') ?> <?= kd_e($invoice['currency']) ?></strong></p></div><?php if($invoice['notes']): ?><p><?= nl2br(kd_e($invoice['notes'])) ?></p><?php endif; ?></section>
